  "data-export-ready": {
    "subject": "Your {{export_name}} export is ready",
    "preheader": "{{row_count}} rows · attached as {{file_type}}",
    "html": "<!DOCTYPE html>\n<html lang=\"en\" xmlns=\"http://www.w3.org/1999/xhtml\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"x-apple-disable-message-reformatting\">\n<meta name=\"color-scheme\" content=\"light\">\n<title>Your {{export_name}} export is ready</title>\n</head>\n<body style=\"margin:0;padding:0;background:#F6F5F2;\">\n<!-- template: data-export-ready | subject: Your {{export_name}} export is ready -->\n<div style=\"display:none;max-height:0;overflow:hidden;mso-hide:all;font-size:1px;line-height:1px;color:#F6F5F2;opacity:0;\">{{row_count}} rows · attached as {{file_type}}&#8203;&nbsp;&#8203;&nbsp;&#8203;&nbsp;&#8203;&nbsp;&#8203;&nbsp;&#8203;&nbsp;</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F6F5F2\" style=\"background:#F6F5F2;\">\n<tr><td align=\"center\" style=\"padding:32px 16px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"width:100%;max-width:600px;background:#FFFFFF;border:1px solid #E6E4DF;border-radius:8px;\">\n<tr><td style=\"padding:20px 32px;background:#201E1F;border-radius:8px 8px 0 0;\">\n<img src=\"{{logo_url}}\" width=\"120\" alt=\"{{org_name}}\" style=\"display:block;border:0;outline:none;height:auto;max-width:120px;\">\n</td></tr>\n<tr><td style=\"height:3px;line-height:3px;font-size:3px;background:#D4AF37;\">&nbsp;</td></tr>\n<tr><td style=\"padding:32px;\">\n<h1 style=\"margin:0 0 16px 0;font-family:Arial,Helvetica,sans-serif;font-size:22px;line-height:30px;font-weight:bold;color:#201E1F;\">Your export is ready</h1>\n<p style=\"margin:0 0 16px 0;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:24px;color:#201E1F;\">The {{export_name}} export you requested on {{requested_at}} IST is attached ({{row_count}} rows).</p>\n<p style=\"margin:0 0 16px 0;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:24px;color:#201E1F;\">{{message}}</p>\n<p style=\"margin:0 0 16px 0;padding:12px 16px;border-left:3px solid #D4AF37;background:#F6F5F2;font-family:Arial,Helvetica,sans-serif;font-size:13px;line-height:20px;color:#201E1F;\">This file contains employee data. Do not forward it outside {{org_name}}.</p>\n<p style=\"margin:0 0 16px 0;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:24px;color:#201E1F;\">Thanks,<br>{{org_name}}</p>\n</td></tr>\n<tr><td style=\"padding:20px 32px;border-top:1px solid #E6E4DF;background:#FAFAF8;border-radius:0 0 8px 8px;\">\n<p style=\"margin:0;font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:18px;color:#5C5859;\">You are receiving this because you have an account at {{org_name}}. Questions? Write to <a href=\"mailto:{{support_email}}\" style=\"color:#201E1F;\">{{support_email}}</a>.</p>\n<p style=\"margin:8px 0 0 0;font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:18px;color:#5C5859;\">{{org_name}} &middot; {{org_address}}</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>\n",
    "text": "Your export is ready\n\nThe {{export_name}} export you requested on {{requested_at}} IST is\nattached ({{row_count}} rows).\n\n{{message}}\n\nThis file contains employee data. Do not forward it outside\n{{org_name}}.\n\nThanks,\n{{org_name}}\n\n--\nYou are receiving this because you have an account at {{org_name}}.\nQuestions? Write to {{support_email}}.\n{{org_name}} · {{org_address}}\n"
  },
